.gradient-btn {
  background: rgb(133, 77, 156);
  background: linear-gradient(90deg, rgb(133, 77, 156) 0%, rgb(208, 78, 214) 100%);
  padding: calc(11px + 4 * (100vw - 320px) / 1600) calc(19px + 13 * (100vw - 320px) / 1600);
  border-radius: calc(3px + 4 * (100vw - 320px) / 1600);
  position: relative;
  border: unset;
  color: #ffffff;
  font-size: calc(14px + 2 * (100vw - 320px) / 1600);
  font-weight: 600;
  z-index: 0;
  margin-top: calc(20px + 13 * (100vw - 320px) / 1600);
}
.gradient-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: calc(3px + 4 * (100vw - 320px) / 1600);
  padding: 1px;
  background: linear-gradient(120deg, rgba(255, 255, 255, 0.5) 0%, rgba(153, 153, 153, 0.5) 100%);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  z-index: -1;
}
.btn-check:checked + .gradient-btn, :not(.btn-check) + .gradient-btn:active, .gradient-btn:first-child:active, .gradient-btn.active, .gradient-btn.show {
  color: #ffffff;
}
.gradient-btn:hover {
  color: #ffffff;
}

