/**=====================
  Country flag css
==========================**/
.intl-tel-input {
  position: relative;
  display: block;
}
.intl-tel-input * {
  box-sizing: border-box;
  -moz-box-sizing: border-box;
}
.intl-tel-input .hide {
  display: none;
}
.intl-tel-input .v-hide {
  visibility: hidden;
}
.intl-tel-input input {
  position: relative;
  z-index: 0;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  padding-right: 36px;
  margin-right: 0;
}
.intl-tel-input input [type=text],
.intl-tel-input input [type=tel] {
  position: relative;
  z-index: 0;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  padding-right: 36px;
  margin-right: 0;
}
.intl-tel-input .flag-container {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  padding: 1px;
}
.intl-tel-input .selected-flag {
  z-index: 1;
  position: relative;
  width: 36px;
  height: 100%;
  padding: 0 8px 0 8px;
}
.intl-tel-input .selected-flag .iti-flag {
  position: absolute;
  top: 0;
  bottom: 0;
  margin: auto;
}
.intl-tel-input .selected-flag .iti-arrow {
  position: relative;
  top: 0;
  margin-top: -2px;
  right: 0;
  width: 0;
  height: 0;
  border-left: 3px solid transparent;
  border-right: 3px solid transparent;
  border-top: 4px solid #555;
}
.intl-tel-input .selected-flag .iti-arrow.up {
  border-top: none;
  border-bottom: 4px solid #555;
}
.intl-tel-input .flag-box {
  display: inline-block;
  width: 20px;
  vertical-align: middle;
  margin-right: 6px;
}
.intl-tel-input .divider {
  padding-bottom: 5px;
  margin-bottom: 5px;
  border-bottom: 1px solid #ccc;
}
.intl-tel-input .country {
  padding: 0;
  display: flex;
  align-items: center;
  width: 100%;
}
.intl-tel-input .country .dial-code {
  color: #999;
}
.intl-tel-input .country.highlight {
  background-color: #efefe7;
}
.intl-tel-input .country-name {
  vertical-align: middle;
  margin-right: 6px;
}
.intl-tel-input .dial-code {
  vertical-align: middle;
}
.intl-tel-input .country-listing {
  position: absolute;
  z-index: 2;
  list-style: none;
  text-align: left;
  padding: 0;
  margin: 0 0 0 -1px;
  box-shadow: 1px 1px 4px rgba(0, 0, 0, 0.2);
  background-color: #ffffff;
